21,"express":true,"vd":null,"status":"publicado","stock":100,"track":true,"variants":[{"n":"600 ml","p":15,"c":null,"sku":"D09-1"}]},{"store":"Pulpería Doña Ana - Central","name":"Galletas de soda","desc":"Paquete de 10","cat":"abarr","kg":"0.35","l":24,"w":12,"h":6,"express":true,"vd":null,"status":"publicado","stock":56,"track":true,"variants":[{"n":"Paquete","p":45,"c":50,"sku":"D10-1"}]},{"store":"Pulpería Doña Ana - Central","name":"Saco de arroz 50 lb","desc":"Para negocios","cat":"gran","kg":"22.7","l":80,"w":45,"h":15,"express":false,"vd":null,"status":"publicado","stock":16,"track":true,"variants":[{"n":"50 lb","p":780,"c":null,"sku":"D11-1"}]},{"store":"Pulpería Doña Ana - Central","name":"Caja de gaseosa cola","desc":"12 botellas de 600 ml","cat":"gas","kg":"9","l":40,"w":28,"h":26,"express":false,"vd":null,"status":"publicado","stock":29,"track":true,"variants":[{"n":"Caja de 12","p":276,"c":300,"sku":"D12-1"}]}]'::jsonb) as t(
    store text, name text, "desc" text, cat text, kg numeric, l numeric, w numeric, h numeric, express boolean,
    vd int, status text, stock int, track boolean, variants jsonb)
), cats(key, name) as (values ('cafe', 'Café y té'), ('carn', 'Carnes'), ('pan', 'Panadería'), ('comi', 'Comida preparada'), ('farm', 'Farmacia y salud'), ('ferr', 'Ferretería'), ('lib', 'Librería y papelería'), ('hogar', 'Hogar y limpieza'), ('verd', 'Verduras y frutas'), ('masc', 'Mascotas'), ('art', 'Artesanías'), ('elec', 'Electrónica y tecnología'), ('grand', 'Electrodomésticos y muebles'), ('ropa', 'Ropa y accesorios'), ('abar', 'Abarrotes y bebidas'), ('rep', 'Repostería y postres'), ('abarr', 'Abarrotes'), ('gas', 'Gaseosas'), ('lact', 'Lácteos y huevos'), ('gran', 'Granos y cereales'), ('beb', 'Bebidas')),
ins as (
  insert into commerce.products (store_id, name, description, category_id, status, express_eligible, weight_kg, length_cm, width_cm, height_cm, validation_days)
  select s.id, st.name, st."desc", m.id, st.status, st.express, st.kg, st.l, st.w, st.h, st.vd
  from stage st
  join commerce.stores s on s.name = st.store
  join cats on cats.key = st.cat
  join commerce.master_items m on m.kind = 'categoria' and m.name = cats.name
  where not exists (select 1 from commerce.products p where p.store_id = s.id and lower(btrim(p.name)) = lower(btrim(st.name)) and p.status <> 'archivado')
  returning id, store_id, name
), vars as (
  insert into commerce.product_variants (product_id, store_id, name, sku, price, compare_at_price)
  select ins.id, ins.store_id, v->>'n', v->>'sku', (v->>'p')::numeric, nullif(v->>'c', '')::numeric
  from ins
  join commerce.stores s on s.id = ins.store_id
  join stage st on st.store = s.name and st.name = ins.name
  cross join lateral jsonb_array_elements(st.variants) v
  returning id, store_id, product_id
), inv as (
  insert into commerce.inventory (variant_id, store_id, track_stock, quantity)
  select vars.id, vars.store_id, st.track, case when st.track then st.stock else 0 end
  from vars
  join ins on ins.id = vars.product_id
  join commerce.stores s on s.id = ins.store_id
  join stage st on st.store = s.name and st.name = ins.name
  returning variant_id, store_id, quantity, track_stock
)
insert into commerce.stock_movements (variant_id, store_id, kind, delta, quantity_after, reason)
select variant_id, store_id, 'entrada', quantity, quantity, 'Existencias iniciales del catálogo demo'
from inv where track_stock and quantity > 0;

